// tabela das rotas /assistente: cada operacao diz o método, a rota e o que vai na query ou no corpo.
// canal e id_externo vêm sempre do Principal (Normalizador), nunca da IA
const BASE = 'https://grupo13-backend-megw.onrender.com/assistente';
const e = $json;
const conversa = { canal: e.canal, id_externo: e.id_externo };

// tira o que veio vazio, para não mandar ?marca= (o backend recusa)
const semVazios = (obj) => Object.fromEntries(
  Object.entries(obj).filter(([, valor]) => valor !== undefined && valor !== null && valor !== ''
    && !(Array.isArray(valor) && !valor.length)),
);
// a IA pode mandar "Casa Lorenzi" ou "Vulto": o backend só aceita lorenzi ou vulto
const marca = ['lorenzi', 'vulto'].find((m) => String(e.marca ?? '').toLowerCase().includes(m));
// link do carrinho: um ou mais id_variante ("12, 34" ou uma lista), até 10, repetidos na query
const variantes = [...new Set([].concat(e.id_variante ?? []).join(',').split(/\D+/).filter(Boolean).map(Number))].slice(0, 10);

const ROTAS = {
  // sem login (ferramentas da IA)
  buscar_pecas:  { metodo: 'GET', rota: '/pecas', query: { descricao: e.descricao, cor: e.cor, tamanho: e.tamanho, marca, categoria: e.categoria } },
  ver_estoque:   { metodo: 'GET', rota: '/estoque', query: { id_produto: e.id_produto, cor: e.cor, tamanho: e.tamanho } },
  link_carrinho: { metodo: 'GET', rota: '/link-carrinho', query: { id_variante: variantes } },
  lojas:         { metodo: 'GET', rota: '/lojas' },
  vocabulario:   { metodo: 'GET', rota: '/vocabulario' },
  // regras de pontos, entrega e retirada, troca e devolução, pagamento e conta, em texto pronto
  politicas:     { metodo: 'GET', rota: '/politicas' },
  // conversa (fluxo fixo)
  registrar_mensagem: { metodo: 'POST', rota: '/conversa', corpo: conversa },
  mudar_etapa:        { metodo: 'PUT', rota: '/conversa/etapa', corpo: { ...conversa, etapa: e.etapa } },
  anotar_resumo:      { metodo: 'PATCH', rota: '/conversa/resumo', corpo: { ...conversa, avaliacao: e.avaliacao || null, fora_do_tema: e.fora_do_tema === true } },
  // texto da mensagem e da resposta, depois de cada resposta (o backend mascara CPF e código)
  guardar_texto:      { metodo: 'POST', rota: '/conversa/mensagens', corpo: { ...conversa, cliente: String(e.cliente ?? '').slice(0, 5000), assistente: e.assistente ? String(e.assistente).slice(0, 5000) : null } },
  // verificação (fluxo fixo, sem IA)
  pedir_codigo:    { metodo: 'POST', rota: '/verificacao/cpf', corpo: { ...conversa, cpf: e.cpf } },
  conferir_codigo: { metodo: 'POST', rota: '/verificacao/codigo', corpo: { ...conversa, codigo: e.codigo } },
  // com login (ferramentas da IA)
  meus_pontos:    { metodo: 'POST', rota: '/meus-pontos', corpo: conversa },
  extrato_pontos: { metodo: 'POST', rota: '/extrato-pontos', corpo: { ...conversa, marca: marca ?? null } },
  meus_pedidos:   { metodo: 'POST', rota: '/meus-pedidos', corpo: { ...conversa, id_pedido: e.id_pedido || null } },
  // e-mail antes de os pontos vencerem: botões Sim/Não (fluxo fixo) ou a IA, quando o cliente escreve
  lembrete_pontos: { metodo: 'PUT', rota: '/lembrete-pontos', corpo: { ...conversa, aceita: e.aceita === true || e.aceita === 'true' } },
  // chamado: a IA rascunha, o cliente aperta [Enviar] (fluxo fixo) e as mensagens seguintes vão para ele
  rascunhar_chamado:   { metodo: 'PUT', rota: '/chamado/rascunho', corpo: { ...conversa, categoria: e.categoria, assunto: e.assunto, resumo: e.resumo, id_pedido: e.id_pedido || null } },
  abrir_chamado:       { metodo: 'POST', rota: '/chamado', corpo: { ...conversa, conversa: Array.isArray(e.conversa) ? e.conversa : [] } },
  mensagem_no_chamado: { metodo: 'POST', rota: '/chamado/mensagem', corpo: { ...conversa, texto: e.texto } },
};

const chamada = ROTAS[e.operacao];
if (!chamada) throw new Error(`Operação desconhecida: ${e.operacao}`);

return {
  json: {
    operacao: e.operacao,
    metodo: chamada.metodo,
    url: BASE + chamada.rota,
    query: semVazios(chamada.query ?? {}),
    corpo: chamada.corpo ?? {},
    canal: e.canal ?? '',
    id_externo: e.id_externo ?? '',
  },
};

// saída única para quem chamou: { ok, status, dados, detail }.
// Erro de regra (401, 404, 422, 429) vem com o detail pronto para o cliente;
// falha de rede ou backend fora do ar vira status 0
const operacao = $('Monta a chamada').item.json.operacao;
const status = Number($json.statusCode ?? 0);
const ok = status >= 200 && status < 300;
const corpo = $json.body;

let detail = corpo && typeof corpo === 'object' ? corpo.detail : null;
// 422 de validação do FastAPI vem como lista
if (Array.isArray(detail)) detail = detail.map((d) => d.msg).join('; ');

return {
  json: {
    operacao,
    ok,
    status,
    dados: ok ? (corpo === '' ? null : corpo ?? null) : null,
    detail: ok ? null : (detail || 'Não consegui consultar agora.'),
  },
};
